static void check(OSStatus status,const char*action){if(status){fprintf(stderr,"FAIL %s: %d\n",action,(int)status);std::exit(1);}}
int main(int argc,char**argv){if(argc!=2)return 2;void*module=dlopen(argv[1],RTLD_NOW|RTLD_LOCAL);if(!module){fprintf(stderr,"%s\n",dlerror());return 3;}auto factory=(AudioComponentFactoryFunction)dlsym(module,"SynthMavenAUFactory");if(!factory)return 4;AudioComponentDescription desc{'aumu','SyMv','Smvn',0,0};auto component=AudioComponentRegister(&desc,CFSTR("SynthMaven bundle smoke"),0x000300,factory);if(!component)return 5;AudioUnit unit=nullptr;check(AudioComponentInstanceNew(component,&unit),"instantiate actual AU bundle");AudioStreamBasicDescription format{};format.mSampleRate=44100;format.mFormatID=kAudioFormatLinearPCM;format.mFormatFlags=kAudioFormatFlagIsFloat|kAudioFormatFlagIsPacked|kAudioFormatFlagIsNonInterleaved;format.mBytesPerPacket=format.mBytesPerFrame=4;format.mFramesPerPacket=1;format.mChannelsPerFrame=2;format.mBitsPerChannel=32;check(AudioUnitSetProperty(unit,kAudioUnitProperty_StreamFormat,kAudioUnitScope_Output,0,&format,sizeof format),"stereo format");UInt32 maximum=256;check(AudioUnitSetProperty(unit,kAudioUnitProperty_MaximumFramesPerSlice,kAudioUnitScope_Global,0,&maximum,sizeof maximum),"maximum block size");check(AudioUnitInitialize(unit),"initialize AU");UInt32 bytes=0;Boolean writable=false;check(AudioUnitGetPropertyInfo(unit,kAudioUnitProperty_ParameterList,kAudioUnitScope_Global,0,&bytes,&writable),"parameter list");if(bytes/sizeof(AudioUnitParameterID)<1400)return 6;check(MusicDeviceMIDIEvent(unit,0x90,60,100,0),"MIDI note");struct StereoBuffers{UInt32 count;AudioBuffer buffers[2];}audio{};std::vector<float>left(256),right(256);audio.count=2;audio.buffers[0]={1,1024,left.data()};audio.buffers[1]={1,1024,right.data()};double energy=0;for(int n=0;n<40;n++){AudioTimeStamp time{};time.mFlags=kAudioTimeStampSampleTimeValid;time.mSampleTime=n*256;AudioUnitRenderActionFlags flags=0;check(AudioUnitRender(unit,&flags,&time,0,256,(AudioBufferList*)&audio),"render AU");for(int i=0;i<256;i++){if(!std::isfinite(left[i])||!std::isfinite(right[i]))return 7;energy+=std::abs(left[i])+std::abs(right[i]);}}if(energy<=0)return 8;check(AudioUnitUninitialize(unit),"uninitialize AU");check(AudioComponentInstanceDispose(unit),"dispose AU");printf("PASS actual AU bundle: instantiate, %u parameters, MIDI input and finite stereo audio\n",(unsigned)(bytes/sizeof(AudioUnitParameterID)));}
